/bin/zsh -lc "python3 -c 'import csv,math,statistics; f=list(csv.DictReader(open(\"processed/forces.csv\")))+list(csv.DictReader(open(\"processed/forces_b3.csv\"))); logs={r[\"run_id\"]:r for r in csv.DictReader(open(\"data/run_log.csv\"))}; g={}; vals=[]
for a in f:
 r=logs[a[\"run\"]]; t=float(r[\"water_temp_c\"]); mu=2.414e-5*10**(247.8/(t+133.15)); rho=1000*(1-((t+288.9414)/(508929.2*(t+68.12963)))*(t-3.9863)**2); nu=mu/rho; u=float(r[\"speed_m_s\"]); d=float(r[\"diameter_mm\"])/1000; re=u*d/nu; cd=float(a[\"F_mean\"])/(.5*998*u*u*d*.6); vals.append((int(a[\"run\"]),r[\"cylinder\"],re,cd,float(a[\"F_mean\"])))
for omit in (False,True):
 for cyl in sorted(set(v[1] for v in vals)):
  q=[v for v in vals if v[1]==cyl and (not omit or v[0]"'!=17)]; cs=[v[3] for v in q]; print(omit,cyl,min(v[2] for v in q),max(v[2] for v in q),statistics.mean(cs),statistics.stdev(cs))
print("allRe",min(v[2] for v in vals),max(v[2] for v in vals)); print("run17",[v for v in vals if v[0]==17])'"'"

